import sys

def transform(A, B):
    if len(A) != len(B):
        return -1

    count_a = {}
    count_b = {}

    for char in A:
        count_a[char] = count_a.get(char, 0) + 1
    for char in B:
        count_b[char] = count_b.get(char, 0) + 1

    if count_a != count_b:
        return -1

    n = len(A)
    i = n - 1
    j = n - 1

    while i >= 0 and j >= 0:
        if A[i] == B[j]:
            i -= 1
            j -= 1
        else:
            j -= 1

    return n - 1 - i

def main():
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) < 2:
        return
    A = lines[0].strip()
    B = lines[1].strip()
    result = transform(A, B)
    print(result)

if __name__ == "__main__":
    main()
